from nbhelpers import good_notebook, write_notebook
from qorotrain.cli.main import main


def test_init_then_validate_walkthrough(tmp_path, capsys):
    nb = good_notebook(tmp_path / "demo.ipynb")
    out = tmp_path / "experiment.yaml"

    assert main(["init", str(nb), "-o", str(out)]) == 0
    text = capsys.readouterr().out
    assert "tuned  learning_rate: float" in text and "fixed  seed" in text
    assert out.exists()

    # the generated file still has the TODO metric
    assert main(["validate", "-f", str(out), "--skip-broker"]) == 1
    assert "still TODO" in capsys.readouterr().out

    out.write_text(out.read_text().replace("metric: TODO", "metric: reward"))
    assert main(["validate", "-f", str(out), "--skip-broker"]) == 0
    assert "is valid" in capsys.readouterr().out


def test_init_refuses_to_overwrite_without_force(tmp_path, capsys):
    nb = good_notebook(tmp_path / "demo.ipynb")
    out = tmp_path / "experiment.yaml"
    out.write_text("keep me")

    assert main(["init", str(nb), "-o", str(out)]) == 2
    assert "already exists" in capsys.readouterr().err
    assert out.read_text() == "keep me"

    assert main(["init", str(nb), "-o", str(out), "--force"]) == 0
    assert out.read_text().startswith("# Generated by")


def test_init_error_for_an_untagged_notebook(tmp_path, capsys):
    nb = write_notebook(tmp_path / "demo.ipynb", [("lr = 1", [])])
    assert main(["init", str(nb), "-o", str(tmp_path / "e.yaml")]) == 2
    assert "no cell is tagged" in capsys.readouterr().err


def test_init_reports_unreadable_lines(tmp_path, capsys):
    nb = write_notebook(tmp_path / "demo.ipynb", [("lr = 0.1\nenv = gym.make('x')\n", ["parameters"])])
    assert main(["init", str(nb), "-o", str(tmp_path / "e.yaml")]) == 0
    assert "could not read" in capsys.readouterr().out


def test_validate_reports_a_broken_yaml_with_paths(tmp_path, capsys):
    path = tmp_path / "experiment.yaml"
    path.write_text("version: 1\ntuner: {algorithm: nope}\n")
    assert main(["validate", "-f", str(path), "--skip-broker"]) == 1
    err = capsys.readouterr().err
    assert "tuner.algorithm" in err and "application: required" in err


def test_validate_missing_file(tmp_path, capsys):
    assert main(["validate", "-f", str(tmp_path / "nope.yaml")]) == 1
    assert "cannot read file" in capsys.readouterr().err